// DIDI_SOCIAL_FULL_SITE_PAGE_FIX
const http = require("http");
const fs = require("fs");
const path = require("path");

const PORT = Number(process.env.PORT || 3000);
const HOST = "0.0.0.0";
const PUBLIC = path.join(__dirname, "public");
const EMBEDDED_INDEX = Buffer.from("", "base64");

const MIME = {
  ".html":"text/html; charset=utf-8",
  ".css":"text/css; charset=utf-8",
  ".js":"application/javascript; charset=utf-8",
  ".json":"application/json; charset=utf-8",
  ".png":"image/png",
  ".jpg":"image/jpeg",
  ".jpeg":"image/jpeg",
  ".webp":"image/webp",
  ".svg":"image/svg+xml",
  ".ico":"image/x-icon",
  ".mp4":"video/mp4",
  ".webm":"video/webm"
};

function send(res, status, body, type="text/plain; charset=utf-8") {
  res.writeHead(status, {
    "Content-Type": type,
    "Cache-Control": "no-store",
    "X-Content-Type-Options": "nosniff"
  });
  res.end(body);
}

function safeFile(urlPath) {
  const clean = decodeURIComponent((urlPath || "/").split("?")[0]);
  const relative = clean.replace(/^\/+/, "");
  const file = path.resolve(PUBLIC, relative);
  return file.startsWith(path.resolve(PUBLIC)) ? file : null;
}

const server = http.createServer((req, res) => {
  const route = (req.url || "/").split("?")[0];

  if (route === "/api/health") {
    return send(res, 200, JSON.stringify({
      ok: true,
      name: "DİDİ Sosyal Beta",
      version: "1.0.0-beta.1",
      time: new Date().toISOString()
    }), "application/json; charset=utf-8");
  }

  if (route === "/" || route === "/index.html") {
    const diskIndex = path.join(PUBLIC, "index.html");
    return fs.readFile(diskIndex, (err, data) => {
      send(res, 200, err ? EMBEDDED_INDEX : data, "text/html; charset=utf-8");
    });
  }

  const file = safeFile(route);
  if (!file) return send(res, 403, "Yasak");

  fs.stat(file, (err, stat) => {
    if (!err && stat.isFile()) {
      const ext = path.extname(file).toLowerCase();
      res.writeHead(200, {
        "Content-Type": MIME[ext] || "application/octet-stream",
        "X-Content-Type-Options": "nosniff",
        "Cache-Control": ext === ".html" ? "no-store" : "public, max-age=3600"
      });
      return fs.createReadStream(file).pipe(res);
    }

    // SPA routes always return the complete site instead of "Sayfa bulunamadı".
    send(res, 200, EMBEDDED_INDEX, "text/html; charset=utf-8");
  });
});

server.on("error", error => {
  console.error("Sunucu hatası:", error);
  process.exit(1);
});

server.listen(PORT, HOST, () => {
  console.log(`DİDİ Sosyal Tam Site hazır: http://${HOST}:${PORT}`);
});
